let gateCtx=null; const gateAlert=document.getElementById('gateAlert');
const amountEl=document.getElementById('amount'), paymentEl=document.getElementById('paymentMode'), cashReceivedEl=document.getElementById('cashReceived');
function dayStart(){const d=new Date();d.setHours(0,0,0,0);return d.toISOString()}
function updateGateCash(){
  const cash=paymentEl.value==='cash';document.getElementById('gateCashFields').classList.toggle('hidden',!cash);
  if(cash){const total=Number(amountEl.value||0);if(!cashReceivedEl.value||Number(cashReceivedEl.value)<total)cashReceivedEl.value=total?total.toFixed(2):'';const change=Math.max(0,Number(cashReceivedEl.value||0)-total);document.getElementById('gateChangePreview').textContent=SELAccess.money(change)}
}
async function loadGateEntries(){
  const {data,error}=await SELAccess.db().from('gate_fee_records').select('*').gte('entry_at',dayStart()).order('entry_at',{ascending:false}).limit(100);
  if(error){SELAccess.alertBox(gateAlert,error.message,'error');return}
  const rows=data||[]; document.getElementById('entryCount').textContent=rows.reduce((s,r)=>s+Number(r.persons_count||0),0).toLocaleString('en-NG'); document.getElementById('entryTotal').textContent=SELAccess.money(rows.reduce((s,r)=>s+Number(r.amount||0),0));
  document.getElementById('gateRows').innerHTML=rows.length?rows.map(r=>`<tr><td><strong>${SELAccess.esc(r.receipt_no)}</strong></td><td>${new Date(r.entry_at).toLocaleTimeString('en-NG',{hour:'2-digit',minute:'2-digit'})}</td><td>${Number(r.persons_count||1)}</td><td><span class="badge">${SELAccess.esc(r.payment_mode)}</span></td><td>${SELAccess.money(r.amount)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No entries recorded today.</td></tr>';
}
paymentEl.addEventListener('change',updateGateCash);amountEl.addEventListener('input',updateGateCash);cashReceivedEl.addEventListener('input',()=>{const change=Math.max(0,Number(cashReceivedEl.value||0)-Number(amountEl.value||0));document.getElementById('gateChangePreview').textContent=SELAccess.money(change)});
document.getElementById('gateForm').addEventListener('submit',async e=>{e.preventDefault();SELAccess.clearAlert(gateAlert);const btn=document.getElementById('saveGate');btn.disabled=true;try{const amount=Number(amountEl.value),payment=paymentEl.value,cashReceived=payment==='cash'?Number(cashReceivedEl.value||0):null;if(payment==='cash'&&cashReceived<amount)throw new Error('Cash received cannot be less than the entry fee total.');const change=payment==='cash'?cashReceived-amount:0;const payload={receipt_no:'GATE-'+Date.now(),amount,persons_count:Number(document.getElementById('personsCount').value),payment_mode:payment,payer_name:document.getElementById('payerName').value.trim()||null,notes:document.getElementById('notes').value.trim()||null,recorded_by:gateCtx.user.id,cash_received:cashReceived,change_given:change};const {data,error}=await SELAccess.db().from('gate_fee_records').insert(payload).select().single();if(error)throw error;SELAccess.alertBox(gateAlert,'Gate entry recorded successfully.');document.getElementById('gateReceipt').className='receipt show';document.getElementById('gateReceipt').innerHTML=`<h4>SEL Center - Gate Entry</h4><div class="receipt-line"><span>Receipt</span><strong>${SELAccess.esc(data.receipt_no)}</strong></div><div class="receipt-line"><span>Visitors</span><strong>${data.persons_count}</strong></div><div class="receipt-line"><span>Payment</span><strong>${SELAccess.esc(data.payment_mode)}</strong></div><div class="receipt-line"><span>Total</span><strong>${SELAccess.money(data.amount)}</strong></div>${payment==='cash'?`<div class="receipt-line"><span>Cash received</span><strong>${SELAccess.money(data.cash_received)}</strong></div><div class="receipt-line"><span>Change</span><strong>${SELAccess.money(data.change_given)}</strong></div>`:''}`;document.getElementById('printGateReceipt')?.classList.remove('hidden');e.target.reset();document.getElementById('personsCount').value=1;updateGateCash();await loadGateEntries();}catch(err){SELAccess.alertBox(gateAlert,err.message,'error')}finally{btn.disabled=false}});

document.getElementById('printGateReceipt')?.addEventListener('click',async()=>{try{await SELReceiptPrinter.printElement('gateReceipt',{title:'SEL Center Gate Entry Receipt',subtitle:'Gate Entry Receipt'});}catch(err){SELAccess.alertBox(gateAlert,err.message||'Unable to print receipt.','error')}});
document.getElementById('refreshGate').addEventListener('click',loadGateEntries);
document.addEventListener('DOMContentLoaded',async()=>{gateCtx=await SELAccess.ensureAuth('gate_entry');if(gateCtx){updateGateCash();loadGateEntries()}});
